import { KALIBRE, lookAlike } from '../../../apps/supplier/lib/documents.js';

/**
 * Disguised invoices for the checker's model questions (9 Oct): the tricks code cannot see,
 * because they are written in prose rather than in a field code compares. A changed bank in a
 * postscript, a payment link, a note to "AI assistants", a fee the quote never listed, a
 * different company issuing "on behalf of" the supplier. And the innocent sentences that look
 * like them ("our details have not changed", "generated by our invoicing software"), which must
 * not hold a payment. Each is labelled with what a careful person would decide.
 *
 * Every invoice keeps the fields code checks right (the sender, the printed address, the amounts,
 * the number), so the model is the one asked. Written in the text form the supplier site sends.
 */
export type Key =
  'same_supplier' | 'pays_elsewhere' | 'bank_elsewhere' | 'instructions' | 'on_order';
/** flag: a careful person would stop the payment. clear: they would pay. any: either is fair. */
export type Label = 'flag' | 'clear' | 'any';
export type Line = { description: string; quantity: number; unitMicro: number };
export type Case = {
  id: string;
  /** What the invoice does, in a few words. */
  about: string;
  /** usdc: the checker on a USDC payment. bank: the advice on a bank transfer (Slice 17). */
  path: 'usdc' | 'bank';
  lines?: Line[];
  /** Text after the payment line: notes, footers, postscripts. */
  notes?: string[];
  /** For a bank invoice, its payment line (default: the account on file). */
  bankLine?: string;
  /** What a careful person decides on each question; a question not named is "clear". */
  expect: Partial<Record<Key, Label>>;
  /** Tests the wider definition of instructions (a claim of approval), not only its wording. */
  widened?: true;
};

