const usdcOf = (micro: number) => (micro / 1e6).toFixed(6).replace(/0+$/, '').replace(/\.$/, '');

/** The invoice as the supplier site's text form writes it, and its total in micro-USDC. */
export function invoiceText(c: Case, number: string): { text: string; totalMicro: number } {
  const lines = c.lines ?? [PHOTOS];
  const totalMicro = lines.reduce((t, l) => t + l.quantity * l.unitMicro, 0);
  const text = [
    `${KALIBRE.name} — ${KALIBRE.tagline}`,
    `Invoice ${number}`,
    'Issued 9 October 2026, due 23 October 2026',
    'Reference: Kalibre Studio quote Q-2210: 50 product photos',
    ...lines.map(
      (l) =>
        `${l.description} x${String(l.quantity)} at ${usdcOf(l.unitMicro)} USDC: ${usdcOf(l.quantity * l.unitMicro)} USDC`,
    ),
    `Total: ${usdcOf(totalMicro)} USDC`,
    ...(c.path === 'bank'
      ? ['Prefer a bank transfer? Our account is below.', c.bankLine ?? ON_FILE_BANK]
      : []),
    `Pay in USDC on Monad to ${KALIBRE.payTo}`,
    ...(c.notes ?? []),
    `Website: ${KALIBRE.website}`,
    `Questions: ${KALIBRE.email}`,
  ].join('\n');
  return { text, totalMicro };
}
